/* RESTDataware offline Bootstrap-compatible behavior */
document.addEventListener('click',function(e){var t=e.target.closest('[data-bs-toggle]');if(!t)return;var kind=t.getAttribute('data-bs-toggle'),sel=t.getAttribute('data-bs-target')||t.getAttribute('href');if(kind==='collapse'&&sel){var x=document.querySelector(sel);if(x)x.classList.toggle('show')}if(kind==='modal'&&sel){var m=document.querySelector(sel);if(m)m.style.display='block'}if(kind==='offcanvas'&&sel){var o=document.querySelector(sel);if(o)o.style.display='block'}});window.bootstrap=window.bootstrap||{};